<?php require 'config/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();try{$nama=trim($_POST['nama']??'');$email=trim($_POST['email']??'');$nim=trim($_POST['nim']??'');$pw=$_POST['password']??'';if(!$nama||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$nim||strlen($pw)<8)throw new Exception('Isi data wajib dan password minimal 8 karakter');if($pw!==($_POST['konfirmasi_password']??''))throw new Exception('Konfirmasi password tidak cocok');$ktm=upload_img('ktm','ktm');$role=($_POST['role']??'')==='penjual'?'penjual':'pembeli';$s=$pdo->prepare('INSERT INTO users(nama,email,password,role,nim,fakultas,prodi,whatsapp,ktm,alamat) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$nama,$email,password_hash($pw,PASSWORD_DEFAULT),$role,$nim,trim($_POST['fakultas']??''),trim($_POST['prodi']??''),trim($_POST['whatsapp']??''),$ktm,trim($_POST['alamat']??'')]);$uid=$pdo->lastInsertId();if($role==='penjual')$pdo->prepare('INSERT INTO toko(user_id,nama_toko,deskripsi) VALUES(?,?,?)')->execute([$uid,trim($_POST['nama_toko']??$nama),trim($_POST['deskripsi_toko']??'')]);flash('Akun berhasil dibuat. Silakan login.');header('Location: login.php');exit;}catch(Throwable $e){$err=$e instanceof PDOException?'Email/NIM sudah digunakan atau struktur tabel tidak sesuai.':$e->getMessage();}}headpage('Daftar');?><div class="panel p-4 mx-auto" style="max-width:760px"><h2>Daftar akun</h2><?php if(isset($err)):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(token())?>"><div class="row g-3"><?php foreach(['nama'=>'Nama lengkap','email'=>'Email','nim'=>'NIM','fakultas'=>'Fakultas','prodi'=>'Program studi','whatsapp'=>'WhatsApp','alamat'=>'Alamat'] as $k=>$v):?><div class="col-md-6"><label><?=$v?></label><input class="form-control" name="<?=$k?>" <?=in_array($k,['nama','email','nim'])?'required':''?>></div><?php endforeach;?><div class="col-md-6"><label>Password (minimal 8)</label><input type="password" name="password" class="form-control" minlength="8" required></div><div class="col-md-6"><label>Konfirmasi password</label><input type="password" name="konfirmasi_password" class="form-control" required></div><div class="col-md-6"><label>Role</label><select name="role" id="role" class="form-select"><option value="pembeli">Pembeli</option><option value="penjual">Penjual</option></select></div><div class="col-md-6"><label>KTM</label><input type="file" name="ktm" accept="image/*" class="form-control"></div><div id="shop" class="row g-3 d-none"><div class="col-md-6"><label>Nama toko</label><input name="nama_toko" class="form-control"></div><div class="col-md-6"><label>Deskripsi toko</label><input name="deskripsi_toko" class="form-control"></div></div><div class="col-12"><button class="btn btn-green">Daftar</button></div></div></form><p class="mt-3"><a href="login.php">Sudah punya akun? Login</a></p></div><script>role.onchange=()=>shop.classList.toggle('d-none',role.value!=='penjual')</script><?php footpage();?>
